SELECT m.id AS merchant_id, m.merchant_name, m.status AS merchant_status, s.id AS store_id, s.store_name, s.address, s.status AS store_status, p.city_code AS city_code, sp.intro AS intro, sp.avatar_asset_id AS avatar_asset_id, sp.promo_level AS promo_level, sp.promo_title AS promo_title, sp.promo_text AS promo_text FROM merchant_store s INNER JOIN merchant m ON m.id = s.merchant_id LEFT JOIN merchant_profile_compat p ON p.merchant_id = m.id LEFT JOIN merchant_store_profile sp ON sp.store_id = s.id WHERE s.id IN
#{storeId}
ORDER BY s.id ASC
